/**
 * The one `cn`: clsx's joining and tailwind-merge's conflict resolution, from the `cn`
 * package, bound to tables compiled for the classes this client uses (`cn-tables.ts`,
 * generated by the `cn` plugin in vite.config.ts — do not edit it by hand). Vite resolves
 * a bare `import { cn } from "cn"` here too, so the CLI's components get the same one.
 */
import { createCn } from "cn/engine"
import tables from "./cn-tables.ts"

export const cn = createCn(tables)
